-- Generated by scripts/generate-upload-limits-migration.mjs. No file deletion.
-- Existing objects and finalized deliveries retain their data and access.
create function public.app_upload_max_bytes(p_bucket text) returns bigint
language sql immutable set search_path='' as $$ select case p_bucket when 'public-media' then 10485760 when 'course-videos' then 50000000 when 'course-resources' then 50000000 when 'protected-books' then 50000000 when 'workshop-recordings' then 50000000 else 0 end::bigint $$;
revoke all on function public.app_upload_max_bytes(text) from public,anon,authenticated;
grant execute on function public.app_upload_max_bytes(text) to service_role;

alter function public.begin_protected_upload_intent(uuid,text,uuid,text,text,text,bigint) rename to begin_protected_upload_intent_before_110;
revoke all on function public.begin_protected_upload_intent_before_110(uuid,text,uuid,text,text,text,bigint) from public,anon,authenticated,service_role;
create function public.begin_protected_upload_intent(p_actor_id uuid,p_upload_kind text,p_entity_id uuid,p_storage_path text,p_path_hash text,p_declared_mime text,p_declared_size bigint) returns uuid
language plpgsql security definer set search_path='' as $$
declare bucket text;
begin
 if p_actor_id is null or not public.has_permission('learning.manage',p_actor_id) then raise exception using errcode='42501',message='learning_management_required';end if;
 bucket:=case p_upload_kind when 'book' then 'protected-books' when 'lesson-video' then 'course-videos' when 'lesson-resource' then 'course-resources' when 'workshop-resource' then 'course-resources' when 'workshop-recording' then 'workshop-recordings' end;
 if p_declared_size is null or p_declared_size<1 or p_declared_size>public.app_upload_max_bytes(bucket) then raise exception using errcode='22023',message='protected_upload_declaration_invalid';end if;
 return public.begin_protected_upload_intent_before_110(p_actor_id,p_upload_kind,p_entity_id,p_storage_path,p_path_hash,p_declared_mime,p_declared_size);
end $$;
revoke all on function public.begin_protected_upload_intent(uuid,text,uuid,text,text,text,bigint) from public,anon,authenticated;
grant execute on function public.begin_protected_upload_intent(uuid,text,uuid,text,text,text,bigint) to service_role;

alter function public.bind_validated_protected_upload(uuid,uuid,text,text,text,bigint,text,boolean) rename to bind_validated_protected_upload_before_110;
revoke all on function public.bind_validated_protected_upload_before_110(uuid,uuid,text,text,text,bigint,text,boolean) from public,anon,authenticated,service_role;
create function public.bind_validated_protected_upload(p_actor_id uuid,p_intent_id uuid,p_title text,p_version text,p_observed_mime text,p_observed_size bigint,p_validation_method text,p_published boolean default false) returns jsonb
language plpgsql security definer set search_path='' as $$
declare i public.protected_upload_intents%rowtype;bucket text;
begin
 if p_actor_id is null or not public.has_permission('learning.manage',p_actor_id) then raise exception using errcode='42501',message='learning_management_required';end if;
 select * into i from public.protected_upload_intents where id=p_intent_id and actor_id=p_actor_id for update;
 if not found then raise exception using errcode='42501',message='protected_upload_intent_invalid';end if;
 bucket:=case i.upload_kind when 'book' then 'protected-books' when 'lesson-video' then 'course-videos' when 'workshop-recording' then 'workshop-recordings' else 'course-resources' end;
 if i.status<>'finalized' and (p_observed_size is null or p_observed_size<1 or p_observed_size>public.app_upload_max_bytes(bucket) or i.declared_size>public.app_upload_max_bytes(bucket)) then raise exception using errcode='22023',message='protected_upload_declaration_invalid';end if;
 return public.bind_validated_protected_upload_before_110(p_actor_id,p_intent_id,p_title,p_version,p_observed_mime,p_observed_size,p_validation_method,p_published);
end $$;
revoke all on function public.bind_validated_protected_upload(uuid,uuid,text,text,text,bigint,text,boolean) from public,anon,authenticated;
grant execute on function public.bind_validated_protected_upload(uuid,uuid,text,text,text,bigint,text,boolean) to service_role;

-- Tighten only these Admin buckets; never increase a stricter existing cap.
update storage.buckets set file_size_limit=least(coalesce(file_size_limit,public.app_upload_max_bytes(id)),public.app_upload_max_bytes(id)) where public.app_upload_max_bytes(id)>0;

-- Keep registration and audit atomic. A lost reply/retry must never remove an
-- already registered object or create a second library item.
create or replace function public.admin_register_media(p_actor uuid,p_data jsonb) returns uuid
language plpgsql security definer set search_path='' as $$
declare a public.media_assets%rowtype; found_id uuid; object_meta jsonb;
begin
 if p_actor is null or not public.has_permission('media.manage',p_actor) then raise exception using errcode='42501',message='media_management_required';end if;
 if jsonb_typeof(p_data)<>'object' or octet_length(p_data::text)>65536 then raise exception 'media_metadata_invalid';end if;
 a:=jsonb_populate_record(null::public.media_assets,p_data);
 if a.bucket not in ('public-media','course-videos','course-resources','protected-books','workshop-recordings')
  or a.path !~ '^admin/\d{4}-\d{2}-\d{2}/[0-9a-f-]{36}-[^/]+$' or a.size_bytes is null or a.size_bytes<1 or a.size_bytes>public.app_upload_max_bytes(a.bucket)
  or (a.bucket='public-media' and a.size_bytes>public.app_upload_max_bytes('public-media')) or char_length(a.title)<1 or char_length(a.title)>180 then raise exception 'media_metadata_invalid';end if;
 perform pg_advisory_xact_lock(hashtextextended('media-register:'||a.bucket||':'||a.path,0));
 select id into found_id from public.media_assets where bucket=a.bucket and path=a.path;
 if found then
  if not exists(select 1 from public.media_assets where id=found_id and uploaded_by=p_actor) then raise exception using errcode='42501',message='media_actor_mismatch';end if;
  return found_id;
 end if;
 select metadata into object_meta from storage.objects where bucket_id=a.bucket and name=a.path;
 if not found or (object_meta->>'size')::bigint is distinct from a.size_bytes or object_meta->>'mimetype' is distinct from a.mime_type then raise exception 'media_object_unconfirmed';end if;
 insert into public.media_assets(bucket,path,title,alt,tags,kind,size_bytes,mime_type,original_name,visibility,uploaded_by,caption,credit,rights_status,rights_reference,folder,focal_x,focal_y,processing_status)
 values(a.bucket,a.path,a.title,a.alt,a.tags,a.kind,a.size_bytes,a.mime_type,a.original_name,case when a.bucket='public-media' then 'public' else 'private' end,p_actor,a.caption,a.credit,a.rights_status,a.rights_reference,a.folder,a.focal_x,a.focal_y,'original') returning id into found_id;
 insert into public.audit_logs(actor_id,action,entity_type,entity_id,meta) values(p_actor,'media.uploaded','media_asset',found_id::text,jsonb_build_object('bucket',a.bucket,'kind',a.kind,'size',a.size_bytes));
 return found_id;
end $$;
revoke all on function public.admin_register_media(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.admin_register_media(uuid,jsonb) to service_role;
